const keys=new Set();let pointer={x:0,y:0};let stickVec={x:0,y:0},joystickActive=false;
let run=null;
function makeRun(){return{time:0,player:{x:0,y:0,vx:0,vy:0,r:17,hp:selectedHero.hp,maxHp:selectedHero.hp,level:1,xp:0,xpNeed:6,damage:selectedHero.damage,range:selectedHero.range,speed:selectedHero.speed,rate:1,crit:selectedHero.crit,magnet:1,dashCd:0,invuln:0,orbit:0,nova:0,hits:0,aim:0},enemies:[],orbs:[],shots:[],effects:[],particles:[],kills:0,spawnTimer:0,attackTimer:.1,boss:null,bossSpawned:false,shards:0,upgrades:[],wave:1,seed:Math.random()*99999,paused:false,stage:'run'} }
function startRun(){run=makeRun();profile.runs++;save();$('#hudHero').textContent=selectedHero.title;$('#weaponHud').textContent=selectedHero.weapon;$('#damageHud').textContent=run.player.damage;$('#bossbar').classList.remove('show');showScene('run');updateHud();last=performance.now()}
function formatTime(s){s=Math.max(0,Math.floor(s));return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function rand(){run.seed=(run.seed*1664525+1013904223)%4294967296;return run.seed/4294967296}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1350)}
function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=35+Math.random()*150;run.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.45,max:.7,size:1.5+Math.random()*3,color})}}
function spawnEnemy(){if(!run)return;let p=run.player,a=rand()*Math.PI*2,d=Math.max(W,H)*.62+rand()*120,x=p.x+Math.cos(a)*d,y=p.y+Math.sin(a)*d;let t=rand(),type=run.time>60&&t<.14?'stalker':run.time>28&&t<.29?'brute':'wraith';let hp=(type==='brute'?70:type==='stalker'?32:25)*(1+run.time/155);let speed=(type==='brute'?35:type==='stalker'?104:57)*(1+run.time/440);run.enemies.push({x,y,vx:0,vy:0,r:type==='brute'?20:type==='stalker'?12:14,hp,maxHp:hp,speed,type,hit:0,phase:rand()*8,damage:type==='brute'?13:8})}
function spawnBoss(){let p=run.player,a=Math.random()*Math.PI*2;run.boss={x:p.x+Math.cos(a)*530,y:p.y+Math.sin(a)*530,r:43,hp:1600+run.time*4,maxHp:1600+run.time*4,speed:57,hit:0,attack:2.4,phase:0,damage:18};$('#bossbar').classList.add('show');toast('THE RIFT GUARDIAN AWAKENS')}
function updateHud(){if(!run)return;let p=run.player;$('#hpFill').style.width=`${Math.max(0,p.hp/p.maxHp*100)}%`;$('#hpText').textContent=`${Math.ceil(p.hp)} / ${p.maxHp} HP`;$('#xpFill').style.width=`${p.xp/p.xpNeed*100}%`;$('#xpText').textContent=`${p.xp} / ${p.xpNeed} ESSENCE`;$('#hudLevel').textContent=`LVL ${String(p.level).padStart(2,'0')}`;$('#killText').textContent=`${run.kills} KILLS`;$('#timer').textContent=formatTime(run.time);$('#waveLabel').textContent=run.time<60?'WAVE 01 · THE AWAKENING':run.time<120?'WAVE 02 · THE HUNT':run.time<180?'WAVE 03 · THE FALL':'FINAL WAVE · RIFT GUARDIAN';$('#shardRun').textContent=`✦ ${run.shards}`;$('#damageHud').textContent=Math.round(p.damage);$('#dashHud').textContent=p.dashCd<=0?'READY · SPACE':`${p.dashCd.toFixed(1)} SEC`;$('#bossFill').style.width=run.boss?`${Math.max(0,run.boss.hp/run.boss.maxHp*100)}%`:'100%';$('#dashIndicator').textContent=p.dashCd<=0?'SPACE · PHASE DASH':`DASH · ${p.dashCd.toFixed(1)}s`}
function update(dt){if(!run||scene!=='run')return;let p=run.player;run.time+=dt;p.invuln=Math.max(0,p.invuln-dt);p.dashCd=Math.max(0,p.dashCd-dt);
let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+stickVec.x,dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+stickVec.y;let len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}let accel=13;p.vx+=(dx*p.speed-p.vx)*Math.min(1,dt*accel);p.vy+=(dy*p.speed-p.vy)*Math.min(1,dt*accel);if(!len){p.vx*=Math.pow(.03,dt);p.vy*=Math.pow(.03,dt)}p.x+=p.vx*dt;p.y+=p.vy*dt;
// Spawn pressure rises throughout the expedition.
run.spawnTimer-=dt;let interval=Math.max(.24,1.05-run.time/280);if(run.spawnTimer<=0){spawnEnemy();if(run.time>55&&rand()<.25)spawnEnemy();if(run.time>130&&rand()<.4)spawnEnemy();run.spawnTimer=interval}
if(run.time>=180&&!run.bossSpawned){run.bossSpawned=true;spawnBoss()}
for(let i=run.enemies.length-1;i>=0;i--){let e=run.enemies[i],vx=p.x-e.x,vy=p.y-e.y,d=Math.hypot(vx,vy)||1;e.vx+=(vx/d*e.speed-e.vx)*Math.min(1,dt*3);e.vy+=(vy/d*e.speed-e.vy)*Math.min(1,dt*3);e.x+=e.vx*dt;e.y+=e.vy*dt;e.hit=Math.max(0,e.hit-dt);if(d<e.r+p.r+1&&p.invuln<=0){hurt(e.damage);p.invuln=.72} }
if(run.boss){let b=run.boss,dx=p.x-b.x,dy=p.y-b.y,d=Math.hypot(dx,dy)||1;b.vx=(dx/d)*b.speed;b.vy=(dy/d)*b.speed;b.x+=b.vx*dt;b.y+=b.vy*dt;b.phase+=dt;b.hit=Math.max(0,b.hit-dt);b.attack-=dt;if(d<b.r+p.r+8&&p.invuln<=0){hurt(b.damage);p.invuln=.9}if(b.attack<=0){b.attack=3.1;let a=Math.atan2(dy,dx);for(let n=-1;n<=1;n++){let aa=a+n*.25;run.shots.push({x:b.x,y:b.y,vx:Math.cos(aa)*155,vy:Math.sin(aa)*155,r:8,life:4,enemy:true,damage:12,color:'#ff5d9c'})}burst(b.x,b.y,'#ff69a8',14)}}
run.attackTimer-=dt;if(run.attackTimer<=0){let target=null,td=p.range;for(const e of run.enemies){let d=Math.hypot(e.x-p.x,e.y-p.y);if(d<td){td=d;target=e}}if(run.boss){let d=Math.hypot(run.boss.x-p.x,run.boss.y-p.y);if(d<td){td=d;target=run.boss}}if(target){shoot(target);run.attackTimer=.62*p.rate}else run.attackTimer=.12}
if(p.orbit){p.orbit+=dt*2.7;if(Math.random()<dt*14){let ox=p.x+Math.cos(p.orbit)*54,oy=p.y+Math.sin(p.orbit)*54;for(let e of run.enemies)if(Math.hypot(e.x-ox,e.y-oy)<e.r+15)damageEnemy(e,p.damage*.55)}}
for(let i=run.shots.length-1;i>=0;i--){let s=run.shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.enemy){if(Math.hypot(s.x-p.x,s.y-p.y)<p.r+s.r&&p.invuln<=0){hurt(s.damage);p.invuln=.8;s.life=0}}else{for(let e of run.enemies)if(Math.hypot(s.x-e.x,s.y-e.y)<e.r+s.r){damageEnemy(e,s.damage);s.life=0;break}if(run.boss&&Math.hypot(s.x-run.boss.x,s.y-run.boss.y)<run.boss.r+s.r){damageBoss(s.damage);s.life=0}}if(s.life<=0)run.shots.splice(i,1)}
for(let i=run.orbs.length-1;i>=0;i--){let o=run.orbs[i],d=Math.hypot(o.x-p.x,o.y-p.y);if(d<p.magnet*105){o.x+=(p.x-o.x)*Math.min(1,dt*4);o.y+=(p.y-o.y)*Math.min(1,dt*4)}if(d<p.r+o.r+5){p.xp+=o.value;run.shards+=o.value>=4?1:0;run.orbs.splice(i,1);if(p.xp>=p.xpNeed)levelUp()}}
for(let i=run.particles.length-1;i>=0;i--){let q=run.particles[i];q.x+=q.vx*dt;q.y+=q.vy*dt;q.vx*=.96;q.vy*=.96;q.life-=dt;if(q.life<=0)run.particles.splice(i,1)}
if(run.boss&&run.boss.hp<=0){run.boss=null;$('#bossbar').classList.remove('show');burst(p.x,p.y,'#ffe38b',55);finishRun(true,false)}
if(p.hp<=0)finishRun(false,false);updateHud()}

