function shoot(target){let p=run.player,dx=target.x-p.x,dy=target.y-p.y,d=Math.hypot(dx,dy)||1,crit=Math.random()<p.crit,damage=p.damage*(crit?2:1);let speed=540;run.shots.push({x:p.x+dx/d*18,y:p.y+dy/d*18,vx:dx/d*speed,vy:dy/d*speed,r:6,life:1.2,damage,enemy:false,color:crit?'#ffe593':selectedHero.color});run.effects.push({x:p.x,y:p.y,angle:Math.atan2(dy,dx),life:.16,max:.16,color:crit?'#ffe593':selectedHero.color});p.hits++;if(p.nova&&p.hits%6===0){for(let i=0;i<12;i++){let a=Math.PI*2*i/12;run.shots.push({x:p.x,y:p.y,vx:Math.cos(a)*400,vy:Math.sin(a)*400,r:7,life:.65,damage:p.damage*.75,enemy:false,color:'#f9aaff',pierce:true})}burst(p.x,p.y,'#f9aaff',12)}}
function damageEnemy(e,damage){if(!run||!run.enemies.includes(e))return;e.hp-=damage;e.hit=.12;burst(e.x,e.y,e.type==='brute'?'#ff9b71':'#db8ff6',3);if(e.hp<=0){let idx=run.enemies.indexOf(e);if(idx<0)return;run.enemies.splice(idx,1);run.kills++;run.orbs.push({x:e.x,y:e.y,r:e.type==='brute'?8:6,value:e.type==='brute'?3:1,phase:Math.random()*5});if(Math.random()<.12)run.shards++;}}
function damageBoss(d){if(!run?.boss)return;run.boss.hp-=d;run.boss.hit=.12;if(Math.random()<.32)burst(run.boss.x+(Math.random()-.5)*60,run.boss.y+(Math.random()-.5)*60,'#ffb0ca',2)}
function hurt(amount){let p=run.player;p.hp=Math.max(0,p.hp-amount);$('#flash').style.opacity='.35';setTimeout(()=>$('#flash').style.opacity='0',90);burst(p.x,p.y,'#ff637c',5)}
function levelUp(){let p=run.player;p.xp-=p.xpNeed;p.level++;p.xpNeed=Math.floor(p.xpNeed*1.36+3);p.hp=Math.min(p.maxHp,p.hp+12);run.stage='upgrade';showChoices();toast('LEVEL UP')}
function showChoices(){let choices=[...upgrades].sort(()=>Math.random()-.5).slice(0,3);let el=$('#upgradeCards');el.innerHTML='';for(let u of choices){let rank=run.upgrades.filter(x=>x===u.id).length;let b=document.createElement('button');b.className='upgrade';b.innerHTML=`<div class="uicon">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}</p><div class="up-rank">${rank?'RANK '+(rank+1)+' · ':'NEW POWER · '}CHOOSE TO EVOLVE</div>`;b.onclick=()=>applyUpgrade(u);el.append(b)}showScene('upgrade')}
