function pause(){if(scene!=='run')return;showScene('pause')}
function draw(){ctx.clearRect(0,0,W,H);let t=run?run.time:performance.now()/1000,cx=run?run.player.x:Math.sin(t*.09)*100,cy=run?run.player.y:Math.cos(t*.07)*70,world=selectedWorld||worlds[0],ox=W/2-cx,oy=H/2-cy;ctx.save();ctx.translate(ox,oy);drawFloor(cx,cy,world,t);if(run){for(const o of run.orbs)drawOrb(o,t);for(const s of run.shots)drawShot(s);for(const e of run.enemies)drawEnemy(e,t);if(run.boss)drawBoss(run.boss,t);for(const q of run.particles){ctx.globalAlpha=Math.max(0,q.life/q.max);ctx.fillStyle=q.color;ctx.beginPath();ctx.arc(q.x,q.y,q.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;for(const e of run.effects){ctx.globalAlpha=e.life/e.max;ctx.strokeStyle=e.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(e.x,e.y,13+(1-e.life/e.max)*15,e.angle-.8,e.angle+.8);ctx.stroke()}ctx.globalAlpha=1;drawPlayer(run.player,t)}else drawAttract(t,world);ctx.restore();requestAnimationFrame(frame)}
function drawFloor(cx,cy,w,t){let bg=ctx.createRadialGradient(cx,cy,20,cx,cy,Math.max(W,H)*.8);bg.addColorStop(0,w.id==='neon'?'#17233a':w.id==='frost'?'#233247':'#292038');bg.addColorStop(.58,w.id==='neon'?'#121b2c':w.id==='frost'?'#1a283a':'#201a30');bg.addColorStop(1,'#0b1020');ctx.fillStyle=bg;ctx.fillRect(cx-W,cy-H,W*2,H*2);
let step=86,left=Math.floor((cx-W/2)/step)-1,right=Math.ceil((cx+W/2)/step)+1,top=Math.floor((cy-H/2)/step)-1,bottom=Math.ceil((cy+H/2)/step)+1;ctx.lineWidth=1;ctx.strokeStyle=w.id==='frost'?'#c5e8ff0a':'#e5d7ff0b';for(let x=left;x<=right;x++)for(let y=top;y<=bottom;y++){let px=x*step+((y%2)*step/2),py=y*step;ctx.beginPath();ctx.arc(px,py,1.3,0,Math.PI*2);ctx.fillStyle='#d9dcff10';ctx.fill();let k=Math.sin(x*11.33+y*37.19);if(k>.994){ctx.fillStyle=w.id==='dusk'?'#eea3d127':w.id==='neon'?'#69ebf522':'#b8e4ff24';ctx.beginPath();ctx.arc(px,py,7,0,Math.PI*2);ctx.fill()}}
// distant boundary and arena sigil
ctx.strokeStyle=w.color+'16';ctx.lineWidth=2;ctx.setLineDash([12,18]);ctx.beginPath();ctx.arc(0,0,940,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=w.accent+'12';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,220,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(0,0,226,0,Math.PI*2);ctx.stroke();ctx.save();ctx.translate(0,0);ctx.rotate(t*.018);ctx.strokeStyle=w.color+'10';ctx.beginPath();for(let i=0;i<6;i++){let a=Math.PI*2*i/6;let x=Math.cos(a)*210,y=Math.sin(a)*210;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.stroke();ctx.restore();
// scattered scenery props, world-locked and sparsely placed
for(let x=left;x<=right;x++)for(let y=top;y<=bottom;y++){let z=Math.sin(x*43.22+y*19.7);if(z>.965){let px=x*step+100*Math.sin(y),py=y*step+80*Math.cos(x);if(w.id==='dusk'){ctx.fillStyle='#473250';ctx.fillRect(px-9,py-22,18,44);ctx.fillStyle='#b88cb550';ctx.beginPath();ctx.arc(px,py-27,14,0,Math.PI*2);ctx.fill()}else if(w.id==='neon'){ctx.fillStyle='#0d1426';ctx.fillRect(px-13,py-24,26,48);ctx.fillStyle='#6be8ec44';ctx.fillRect(px-9,py-18,3,8);ctx.fillRect(px+4,py-5,4,10)}else{ctx.fillStyle='#304359';ctx.beginPath();ctx.moveTo(px,py-27);ctx.lineTo(px-15,py+20);ctx.lineTo(px+13,py+15);ctx.closePath();ctx.fill()}}}
}
function drawAttract(t,w){for(let i=0;i<14;i++){let a=t*.12+i*2.39,x=Math.cos(a)*(180+i*23),y=Math.sin(a*.86)*(90+i*14);ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle=i%3===0?w.accent+'88':w.color+'55';ctx.beginPath();ctx.ellipse(0,0,3,7,0,0,Math.PI*2);ctx.fill();ctx.restore()}let glow=ctx.createRadialGradient(0,0,4,0,0,100);glow.addColorStop(0,w.color+'4a');glow.addColorStop(1,w.color+'00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,0,100,0,Math.PI*2);ctx.fill();drawAvatar(0,0,heroes[0].color,t,true)}
function drawAvatar(x,y,color,t,large=false){let s=large?1.4:1;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.shadowColor=color;ctx.shadowBlur=22;ctx.fillStyle=color+'2a';ctx.beginPath();ctx.ellipse(0,11,23,20,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#161c32';ctx.beginPath();ctx.ellipse(0,10,14,18,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,-8,12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff0d4';ctx.beginPath();ctx.arc(0,-9,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#17172c';ctx.beginPath();ctx.arc(0,-12,9,Math.PI,Math.PI*2);ctx.lineTo(7,-7);ctx.lineTo(-8,-8);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-10,6);ctx.lineTo(-21,22+Math.sin(t*7)*2);ctx.lineTo(-4,17);ctx.closePath();ctx.fill();ctx.strokeStyle='#ffffffaa';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(12,5);ctx.lineTo(23,-5);ctx.stroke();ctx.restore()}
function drawPlayer(p,t){if(p.orbit){for(let i=0;i<3;i++){let a=p.orbit+i*Math.PI*2/3,x=p.x+Math.cos(a)*54,y=p.y+Math.sin(a)*54;ctx.shadowColor='#d6a5ff';ctx.shadowBlur=16;ctx.fillStyle='#d8aaff';ctx.beginPath();ctx.arc(x,y,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}}if(p.invuln>0&&Math.floor(t*20)%2===0)ctx.globalAlpha=.5;drawAvatar(p.x,p.y,selectedHero.color,t);ctx.globalAlpha=1}

